export declare const SERVER_DRIVEN_PAGINATION_SOURCE = "const PAGE_SIZE = 50;\n\ntype PageResult<TRow> = { items: TRow[]; total: number };\n\nasync function fetchVolumesPage(page: number): Promise<PageResult<Volume>> {\n  const offset = (page - 1) * PAGE_SIZE;\n  const response = await fetch(`/api/volumes?offset=${offset}&limit=${PAGE_SIZE}`);\n  if (!response.ok) throw new Error(\"fetch failed\");\n  return response.json(); // { items: Volume[], total: number }\n}\n\nfunction VolumesTable() {\n  const [page, setPage] = useState(1);\n  const [total, setTotal] = useState(0);\n  const [rows, setRows] = useState<Volume[]>([]);\n  const [isLoading, setIsLoading] = useState(true);\n\n  useEffect(() => {\n    let cancelled = false;\n    setIsLoading(true);\n    fetchVolumesPage(page)\n      .then((result) => {\n        if (cancelled) return;\n        setRows(result.items);\n        setTotal(result.total);\n      })\n      .finally(() => {\n        if (!cancelled) setIsLoading(false);\n      });\n    return () => { cancelled = true; };\n  }, [page]);\n\n  const totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));\n  const start = total === 0 ? 0 : (page - 1) * PAGE_SIZE + 1;\n  const end = Math.min(page * PAGE_SIZE, total);\n\n  return (\n    <BpTable<Volume>\n      data={rows}\n      columns={volumeColumns}\n      getRowId={(row) => row.id}\n      isLoading={isLoading}\n      name=\"Volumes\"\n      totalCount={total}\n      pagination={{\n        start,\n        end,\n        total,\n        page,\n        onFirstPage: () => setPage(1),\n        onPreviousPage: () => setPage((p) => Math.max(1, p - 1)),\n        onNextPage: () => setPage((p) => Math.min(totalPages, p + 1)),\n        onLastPage: () => setPage(totalPages),\n      }}\n    />\n  );\n}";
